/* Verify the packed layout/endianness against the engine's exact struct defs. */
#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <arpa/inet.h>

static void dump(const char *tag, const void *p, size_t n)
{
    const unsigned char *b = p;
    printf("%s size=%zu ", tag, n);
    for (size_t i = 0; i < n; i++)
        printf("%02x", b[i]);
    printf("\n");
}

int main(void)
{
    /* struct copied verbatim from CalculateCommunityFlowIdv4() */
    struct {
        uint16_t seed;
        uint32_t src;
        uint32_t dst;
        uint8_t proto;
        uint8_t pad0;
        uint16_t sp;
        uint16_t dp;
    } __attribute__((__packed__)) ipv4;

    /* struct copied verbatim from CalculateCommunityFlowIdv6() */
    struct {
        uint16_t seed;
        uint32_t src[4];
        uint32_t dst[4];
        uint8_t proto;
        uint8_t pad0;
        uint16_t sp;
        uint16_t dp;
    } __attribute__((__packed__)) ipv6;

    /* v4 case: 1.2.3.4:12345 -> 5.6.7.8:80 proto 6, seed 0.
     * src < dst so no swap, matching the engine's ordering branch. */
    memset(&ipv4, 0, sizeof(ipv4));
    ipv4.seed = htons(0);
    inet_pton(AF_INET, "1.2.3.4", &ipv4.src);
    inet_pton(AF_INET, "5.6.7.8", &ipv4.dst);
    ipv4.proto = 6;
    ipv4.pad0 = 0;
    ipv4.sp = htons(12345);
    ipv4.dp = htons(80);
    dump("v4", &ipv4, sizeof(ipv4));

    /* v6 case: 2001:db8::1:12345 -> 2001:db8::2:443 proto 6, seed 0. */
    memset(&ipv6, 0, sizeof(ipv6));
    ipv6.seed = htons(0);
    inet_pton(AF_INET6, "2001:db8::1", &ipv6.src);
    inet_pton(AF_INET6, "2001:db8::2", &ipv6.dst);
    ipv6.proto = 6;
    ipv6.pad0 = 0;
    ipv6.sp = htons(12345);
    ipv6.dp = htons(443);
    dump("v6", &ipv6, sizeof(ipv6));

    /* ICMP v4 case: type 8 / 0, proto 1, seed 0. */
    memset(&ipv4, 0, sizeof(ipv4));
    ipv4.seed = htons(0);
    inet_pton(AF_INET, "192.0.2.10", &ipv4.src);
    inet_pton(AF_INET, "192.0.2.20", &ipv4.dst);
    ipv4.proto = 1;
    ipv4.pad0 = 0;
    ipv4.sp = htons(8);
    ipv4.dp = htons(0);
    dump("v4icmp", &ipv4, sizeof(ipv4));
    return 0;
}

